starter.css:
.wrap { width: 360px; }
.session-card {
  padding-top: 12px;
  padding-bottom: 12px;
  border-radius: 12px;
  background: #f8fafc;
}
.session-card h3 { margin: 8px 0; }

.session-card {
  border-left: 6px solid #6d28d9;
  padding-left: 20px;
  padding-right: 8px;
  text-align: left;
}
.time {
  display: inline-block;
  margin-right: 12px;
  color: #6b7280;
}
.more {
  display: block;
  text-align: right;
}
.arrow {
  display: inline-block;
  margin-left: 4px;
}

solution.css:
.wrap { width: 360px; }
.session-card {
  padding-top: 12px;
  padding-bottom: 12px;
  border-radius: 12px;
  background: #f8fafc;
}
.session-card h3 { margin: 8px 0; }

.session-card {
  border-inline-start: 6px solid #6d28d9;
  padding-inline: 20px 8px;
  text-align: start;
}
.time {
  display: inline-block;
  margin-inline-end: 12px;
  color: #6b7280;
}
.more {
  display: block;
  text-align: end;
}
.arrow {
  display: inline-block;
  margin-inline-start: 4px;
}
.arrow:dir(rtl) {
  scale: -1 1;
}
